export function norm(v=''){return String(v).normalize('NFKD').replace(/\p{Diacritic}/gu,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
export function trackKey(t){return t.spotifyId?`spotify:${t.spotifyId}`:`${norm(t.artist)}|${norm(t.title)}|${norm(t.version||'')}`}
export function csvEscape(v){const s=String(v??'');return /[",;\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s}
export function download(name,text,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
export function exportMaster(tracks){const h=['Artist','Title','Version','Album','Year','Country','Label','Genre','Subgenre','BPM','Key','Camelot','Energy','Rating','Crowd Rating','Spotify ID','Spotify URI','Spotify URL','ISRC','Duration ms','Last Played','Play Count','Tags','Playlists','Source','Verified'];const lines=[h.join(',')];for(const t of tracks)lines.push([t.artist,t.title,t.version,t.album,t.year,t.country,t.label,t.genre,t.subgenre,t.bpm,t.key,t.camelot,t.energy,t.rating,t.crowdRating,t.spotifyId,t.spotifyUri,t.spotifyUrl,t.isrc,t.durationMs,t.lastPlayed,t.playCount,(t.tags||[]).join('|'),(t.playlists||[]).join('|'),t.source,t.verified].map(csvEscape).join(','));return lines.join('\n')}
export function exportSoundiiz(tracks){const h=['title','artist','album','isrc','platform','id'];return [h.join(','),...tracks.map(t=>[t.title,t.artist,t.album,t.isrc,'spotify',t.spotifyId].map(csvEscape).join(','))].join('\n')}
export function exportTuneMyMusic(tracks){const h=['Track name','Artist name','Album','ISRC','Spotify URL'];return [h.join(','),...tracks.map(t=>[t.title,t.artist,t.album,t.isrc,t.spotifyUrl].map(csvEscape).join(','))].join('\n')}
export function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quote&&n==='"'){cell+='"';i++;continue}if(c==='"'){quote=!quote;continue}if(!quote&&(c===','||c===';')){row.push(cell);cell='';continue}if(!quote&&(c==='\n'||c==='\r')){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';continue}cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
export function parseImport(text,source='CSV'){const rows=parseCSV(text);if(rows.length<2)return[];const aliases={artist:['artist','artists','artist name','kunstner'],title:['title','track','track name','song','titel'],album:['album','album name'],spotifyId:['spotify id','track id'],spotifyUrl:['spotify url','track url','url'],isrc:['isrc'],year:['year','release year','release date'],genre:['genre'],subgenre:['subgenre','style'],bpm:['bpm','tempo'],key:['key','toneart'],camelot:['camelot'],energy:['energy','energi'],country:['country','land'],label:['label'],version:['version','mix'],playlist:['playlist','playlist name']};const map={};rows[0].forEach((h,i)=>{const n=norm(h);for(const [k,a] of Object.entries(aliases))if(a.some(x=>norm(x)===n)){map[k]=i;break}});const g=(r,k)=>map[k]===undefined?'':String(r[map[k]]||'').trim();return rows.slice(1).map(r=>{const id=g(r,'spotifyId')||crypto.randomUUID();return{id:`spotify:${id}`.includes('spotify:spotify:')?id:`spotify:${id}`,spotifyId:g(r,'spotifyId'),spotifyUri:g(r,'spotifyId')?`spotify:track:${g(r,'spotifyId')}`:'',artist:g(r,'artist'),title:g(r,'title'),album:g(r,'album'),version:g(r,'version'),year:Number(g(r,'year').slice(0,4))||null,country:g(r,'country'),label:g(r,'label'),genre:g(r,'genre'),subgenre:g(r,'subgenre'),bpm:Number(g(r,'bpm'))||null,key:g(r,'key'),camelot:g(r,'camelot'),energy:Number(g(r,'energy'))||5,spotifyUrl:g(r,'spotifyUrl'),isrc:g(r,'isrc'),durationMs:null,playlists:g(r,'playlist')?[g(r,'playlist')]:[],tags:[],rating:0,crowdRating:0,lastPlayed:null,playCount:0,source,verified:false,createdAt:new Date().toISOString()}}).filter(t=>t.artist&&t.title)}
